// SPDX-License-Identifier: MIT
// Generate packages/sdk/src/generated/* from protocol-inputs/contracts (see tools/inputs.mjs). Generated files are
// checked in, carry a header naming their inputs, and are never edited by hand.
//   node tools/codegen.mjs           write
//   node tools/codegen.mjs --check   fail if a regenerated file differs from the checked-in one
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { keccak256, stringToHex } from "viem";
import { fail, ok, ROOT } from "./lib/util.mjs";

const IN = join(ROOT, "protocol-inputs/contracts");
const OUT = join(ROOT, "packages/sdk/src/generated");
const check = process.argv.includes("--check");
const lock = JSON.parse(readFileSync(join(ROOT, "protocol-inputs/lock.json"), "utf8"));
const read = (p) => readFileSync(join(IN, p), "utf8");
const json = (p) => JSON.parse(read(p));
const sha = (s) => createHash("sha256").update(s).digest("hex").slice(0, 16);

/** The contracts the SDK calls, and the export names it uses for their ABIs. */
const ABIS = {
  ledgerAbi: "LedgerCore", // ILedger (execute) + ILedgerHot (nonceOf, publicationAt, executionSet, ...) at the proxy
  ingressAbi: "LedgerIngress", // acceptanceProfileOf, indexFloor, nativeIntentDigest
  ledgerReadsAbi: "LedgerReads",
  ledgerViewsAbi: "LedgerViews",
  lensReaderAbi: "LensReader",
  filesPageReaderAbi: "FilesPageReader",
  web3GatewayAbi: "EfsWeb3Gateway", // ERC-6860 resource requests (web3://)
  indexAbi: "RealmIndex", // IIndexReads: posting heads (the backlink list's live count), coverage, stores
  bitmapStoreAbi: "BitmapStore", // the kind-10 scope lists (a principal's positions under one subject)
  topicMineReaderAbi: "TopicMineReader", // the lens view of a place (mine)
  topicEveryoneReaderAbi: "TopicEveryoneReader", // the public views of a place (everyone, raw)
  topicLookupReaderAbi: "TopicLookupReader", // byName, about, counts, word pages, children
};

function header(inputs) {
  return [
    "// SPDX-License-Identifier: MIT",
    "// GENERATED by tools/codegen.mjs. DO NOT EDIT. Regenerate with `pnpm generate`.",
    `// contracts ${lock.contracts.commit} · inputs: ${inputs.map((p) => `${p}@${lock.contracts.files[p]?.slice(0, 12) ?? "?"}`).join(", ")}`,
    "",
  ].join("\n");
}
const literal = (v) => JSON.stringify(v, null, 2);

const files = {};

// ---- ABIs (functions, events and errors exactly as compiled)
{
  const inputs = Object.values(ABIS).map((n) => `artifacts/${n}.json`);
  let src = header(inputs);
  for (const [exp, name] of Object.entries(ABIS)) {
    const abi = json(`artifacts/${name}.json`).abi;
    src += `/** ${name} ABI (${abi.length} entries). */\nexport const ${exp} = ${literal(abi)} as const;\n\n`;
  }
  // Every custom error across all artifacts, deduplicated by signature, for revert decoding.
  const seen = new Map();
  for (const f of Object.keys(lock.contracts.files).filter((p) => p.startsWith("artifacts/"))) {
    const artifact = json(f);
    if (!Array.isArray(artifact.abi)) continue; // e.g. an index file, not a compiled unit
    for (const e of artifact.abi.filter((x) => x.type === "error")) {
      const sig = `${e.name}(${e.inputs.map((i) => i.type).join(",")})`;
      if (!seen.has(sig)) seen.set(sig, e);
    }
  }
  const errors = [...seen.entries()].sort(([a], [b]) => (a < b ? -1 : 1)).map(([, e]) => e);
  src += `/** Every custom error any EFS contract can revert with (${errors.length}). */\nexport const errorAbi = ${literal(errors)} as const;\n`;
  files["abis.ts"] = src;
}

// ---- Domains, family ids, purposes (opaque protocol identity; never hand-typed)
{
  const ids = json("test/vectors/ids.json");
  let src = header(["test/vectors/ids.json"]);
  src +=
    "/** keccak256 domain tags used in id derivations (Keys.sol). Opaque protocol constants. */\n";
  src += `export const DOMAINS = ${literal(ids.domains)} as const;\n\n`;
  src += "/** Index family ids (Keys.familyId). */\n";
  src += `export const FAMILIES = ${literal(ids.families)} as const;\n\n`;
  src +=
    "/** Golden vectors for the key derivations (used by tests; tree-shaken from builds). */\n";
  src += `export const KEY_VECTORS = ${literal({ inputs: ids.inputs, outputs: ids.outputs })} as const;\n`;
  files["domains.ts"] = src;
}

// ---- Error catalog (meaning + retry class)
{
  const cat = json("release/errors.json");
  const rows = Object.entries(cat.errors).map(([selector, e]) => ({
    selector,
    name: e.name,
    signature: e.signature,
    retryClass: e.retryClass ?? null,
    meaning: e.meaning ?? null,
  }));
  let src = header(["release/errors.json"]);
  src +=
    "/** Contracts error catalog keyed by selector. retryClass null = not yet classified by contracts (C2). */\n";
  src += `export const ERROR_CATALOG: Readonly<Record<string, { name: string; signature: string; retryClass: string | null; meaning: string | null }>> = ${literal(Object.fromEntries(rows.map((r) => [r.selector, { name: r.name, signature: r.signature, retryClass: r.retryClass, meaning: r.meaning }])))};\n`;
  files["errors.ts"] = src;
}

// ---- Protocol constants (release.json `constants`, parsed by contracts from their Solidity sources)
// Nothing here is typed by hand. Every hashed id is re-derived from its preimage, and the purposes are cross-checked
// against how the deployment's own seed and index use them, so a wrong or drifted constant fails codegen.
{
  const dep = json("release/efs-deployment.json");
  const rel = json("release/release.json");
  const c = rel.constants;
  if (!c) throw new Error("codegen: release.json has no `constants`");
  const hashed = (what, entry) => {
    const want = keccak256(stringToHex(entry.preimage));
    if (want !== entry.id.toLowerCase())
      throw new Error(`codegen: ${what} id is not keccak256("${entry.preimage}")`);
    return entry.id.toLowerCase();
  };
  const purposes = Object.fromEntries(
    Object.entries(c.purposes).map(([k, v]) => [k, hashed(`purpose ${k}`, v)]),
  );
  const vocabId = hashed("status vocabulary", c.status);
  const profileVocab = rel.profiles?.statusVocabularyId;
  if (profileVocab && profileVocab.toLowerCase() !== vocabId)
    throw new Error("codegen: constants.status.id disagrees with profiles.statusVocabularyId");

  // Cross-check HEAD and FOLDER against the deployment's seed and index (the derivation codegen used before).
  const ZERO = `0x${"0".repeat(64)}`;
  const folder = dep.index?.units?.[0]?.purposeFilter?.toLowerCase();
  const fileSubjects = new Set((dep.seed?.files ?? []).map((f) => f.subjectId.toLowerCase()));
  const binds = (dep.seed?.transactions ?? [])
    .flatMap((t) => t.actions)
    .filter((a) => a.kind === c.actionKinds.BIND);
  const heads = new Set(
    binds
      .filter((a) => fileSubjects.has(a.subject.toLowerCase()) && a.role === ZERO)
      .map((a) => a.purpose.toLowerCase()),
  );
  if (folder !== purposes.FOLDER)
    throw new Error(
      "codegen: constants FOLDER purpose disagrees with the deployment's index purpose filter",
    );
  if (heads.size !== 1 || !heads.has(purposes.HEAD))
    throw new Error(
      "codegen: constants HEAD purpose disagrees with the deployment's seed head binds",
    );

  const codes = (table) =>
    Object.fromEntries(
      Object.entries(table)
        .filter(([n]) => n !== "0")
        .map(([n, v]) => [Number(n), v]),
    );
  const reserved = (name) => /_RESERVED$/.test(name);
  const fc = c.files;
  if (!Number.isInteger(fc.mediaType?.maxLength))
    throw new Error("codegen: constants.files.mediaType.maxLength is missing");
  let src = header([
    "release/release.json",
    "release/efs-deployment.json",
    "test/vectors/topics.json",
    "test/vectors/numbers.json",
  ]);
  src += `/** Action kinds (Actions.sol). \`*_RESERVED\` kinds are refused by the ledger. */\n`;
  src += `export const ACTION_KINDS = ${literal(c.actionKinds)} as const;\n\n`;
  src += "/** The action kinds a plan may use. */\n";
  src += `export const ACTION = ${literal(Object.fromEntries(Object.entries(c.actionKinds).filter(([k]) => !reserved(k))))} as const;\n\n`;
  src += "/** Deployment capability bits (describe().capabilities). */\n";
  src += `export const CAPABILITIES = ${literal(c.capabilities)} as const;\n\n`;
  src += "/** Binding purpose ids (keccak256 of their preimages, checked at codegen). */\n";
  src += `export const PURPOSES = ${literal({ head: purposes.HEAD, folder: purposes.FOLDER, tag: purposes.TAG, property: purposes.PROPERTY, same: purposes.SAME, broader: purposes.BROADER })} as const;\n\n`;
  src +=
    "/** The status vocabulary this SDK maps. The pin refuses a deployment with another vocabulary id. */\n";
  src += `export const STATUS_VOCABULARY_ID = ${JSON.stringify(vocabId)} as const;\n`;
  src += "/** Reader status codes (Results.sol). 0 is reserved and never returned. */\n";
  src += `export const STATUS_CODES = ${literal(codes(c.status.codes))} as const;\n\n`;
  src += "/** Index coverage codes (Results.sol). 0 is reserved. */\n";
  src += `export const COVERAGE_CODES = ${literal(codes(c.coverage.codes))} as const;\n\n`;
  src += "/** Files body constants (EfsFiles.sol, FilesProfile.sol). */\n";
  src += `export const FILES = ${literal({
    form: fc.form,
    contentCarrier: fc.contentCarrier,
    externalCarrier: fc.externalCarrier,
    hashAlg: fc.hashAlg,
    alias: fc.alias,
    targetKind: fc.targetKind,
    sha256Empty: fc.sha256Empty.toLowerCase(),
    contentVersion: fc.contentVersion,
    externalVersion: fc.externalVersion,
    chunkingId: fc.chunking.id,
    chunkPayload: fc.chunking.chunkPayload,
    mediaTypeMaxLength: fc.mediaType.maxLength,
  })} as const;\n`;
  src += `/** The largest declared length a Files body may carry (uint64). */\nexport const FILES_LENGTH_MAX = ${BigInt(fc.lengthMax)}n;\n\n`;
  // Topics (the tag release): the word and text grammars' limits and refused code points (test/vectors/topics.json,
  // the chain's own table), and the binding number's strength limit (test/vectors/numbers.json).
  const tc = c.topics;
  const tv = json("test/vectors/topics.json");
  const nv = json("test/vectors/numbers.json");
  if (!tc || typeof tc.wordMax !== "number" || typeof tc.textMax !== "number")
    throw new Error("codegen: constants.topics needs wordMax and textMax");
  const refused = (tv.refused?.entries ?? []).map((e) => [e.lo, e.hi, e.class]);
  for (let i = 0; i < refused.length; i++) {
    const [lo, hi, cls] = refused[i];
    if (!(Number.isInteger(lo) && Number.isInteger(hi) && lo <= hi && Number.isInteger(cls)))
      throw new Error(`codegen: topics refused entry ${i} is malformed`);
    if (i > 0 && lo <= refused[i - 1][1])
      throw new Error("codegen: topics refused ranges must be sorted and disjoint");
  }
  if (!Number.isInteger(nv.maxStrength))
    throw new Error("codegen: numbers.json has no maxStrength");
  src +=
    "/** Topics: the word and text limits, the refused-scalar classes and their sorted inclusive ranges [lo, hi, class]. */\n";
  src += `export const TOPICS = ${JSON.stringify({ wordMax: tc.wordMax, textMax: tc.textMax, refusedClasses: tc.refusedClasses, refused })} as const;\n\n`;
  src +=
    "/** The largest strength a BIND or UNBIND carries (BindingNumber.MAX_STRENGTH): numbers run −(max + 1)..max. */\n";
  src += `export const MAX_STRENGTH = ${nv.maxStrength};\n`;
  files["constants.ts"] = src;
}

// ---- Gas model (release.json gasModel, efs-gas-model/1): planning constants per fee schedule. Every row the
// splitter prices is required, so a renamed or missing row fails codegen instead of pricing an action at zero.
{
  const g = json("release/release.json").gasModel;
  if (g?.schema !== "efs-gas-model/1")
    throw new Error("codegen: release.json has no efs-gas-model/1 gasModel");
  const ROWS = [
    "fixed",
    "perWord",
    "perByte",
    "publishExisting",
    "reuse",
    "create",
    "bindHeadFresh",
    "bindHeadRebind",
    "bindFolderFreshFile",
    "bindFolderFreshDirectory",
    "bindFolderRebind",
    "unbindFolder",
    "releaseFolder",
    "withdraw",
    "firstWriteSurcharge",
    // The tag release's TAG rows (a first tag at a fresh pair, a later author's first yes, a number change, a lone
    // negative, a mask, a release and a restore of a tag).
    "bindTagFresh",
    "bindTagSecondAuthor",
    "bindTagNumberChange",
    "unbindTagLone",
    "unbindTag",
    "releaseTag",
    "restoreTag",
    // Statements about topics (contracts 0fb4804): a label (PROPERTY), "same as" and "broader", first and later.
    "bindPropertyFresh",
    "bindPropertyRebind",
    "unbindProperty",
    "releaseProperty",
    "bindSameFreshWord",
    "bindSameFreshPath",
    "unbindSame",
    "releaseSame",
    "restoreSame",
    "bindBroaderFresh",
    "unbindBroader",
    "releaseBroader",
    "restoreBroader",
  ];
  const TAG_LEVELS = ["mineNew", "mineExisting", "sharedNew", "sharedExisting"];
  const constants = (where, c) => {
    for (const k of ROWS)
      if (typeof c?.[k] !== "number" || !Number.isFinite(c[k]))
        throw new Error(`codegen: gasModel ${where}.${k} must be a number`);
    const pn = c.publishNew ?? {};
    if (typeof pn["files-bytes/1"] !== "number")
      throw new Error(`codegen: gasModel ${where}.publishNew needs files-bytes/1`);
    for (const [k, v] of Object.entries(pn))
      if (typeof v !== "number") throw new Error(`codegen: gasModel ${where}.publishNew.${k}`);
    const tl = c.tagLevel ?? {};
    for (const k of TAG_LEVELS)
      if (typeof tl[k] !== "number") throw new Error(`codegen: gasModel ${where}.tagLevel.${k}`);
    return Object.fromEntries([
      ...ROWS.map((k) => [k, c[k]]),
      ["publishNew", pn],
      ["tagLevel", Object.fromEntries(TAG_LEVELS.map((k) => [k, tl[k]]))],
    ]);
  };
  // The kernel's floor inputs, per schedule: every field the planning rule reads is required (formula 2).
  const WORK_MODEL = [
    "formulaVersion",
    "freshPerPublication",
    "rwPerPublication",
    "freshPerPublishFresh",
    "freshPerPublishExisting",
    "rwPerPublish",
    "freshPerBindFresh",
    "rwPerBind",
    "rwPerBindLater",
    "freshPerRef",
    "freshPerDigestSpec",
    "computeBase",
    "computePerAction",
    "computePerHookEffect",
    "finalComputeBase",
    "finalComputePerBind",
    "finalComputePerPublish",
  ];
  const floorOf = (where, f) => {
    const num = (path, v) => {
      if (typeof v !== "number" || !Number.isFinite(v))
        throw new Error(`codegen: gasModel ${where}.${path} must be a number`);
      return v;
    };
    const wm = Object.fromEntries(
      WORK_MODEL.map((k) => [k, num(`workModel.${k}`, f?.workModel?.[k])]),
    );
    const types = {};
    for (const [t, v] of Object.entries(f?.types ?? {}))
      types[t] = { refs: num(`types.${t}.refs`, v.refs), specs: num(`types.${t}.specs`, v.specs) };
    return {
      workModel: wm,
      limits: {
        floorFreshGas: num("limits.floorFreshGas", f?.limits?.floorFreshGas),
        floorRewriteGas: num("limits.floorRewriteGas", f?.limits?.floorRewriteGas),
        kernelTail: num("limits.kernelTail", f?.limits?.kernelTail),
      },
      callGasRetained: {
        numerator: num("callGasRetained.numerator", f?.callGasRetained?.numerator),
        denominator: num("callGasRetained.denominator", f?.callGasRetained?.denominator),
      },
      dispatchOverhead: num("dispatchOverhead", f?.dispatchOverhead),
      types,
      kernel: constants(`${where}.kernel`, f?.kernel),
    };
  };
  const schedules = {};
  for (const [name, sch] of Object.entries(g.schedules ?? {})) {
    if (!Array.isArray(sch.hardforks) || !sch.hardforks.length)
      throw new Error(`codegen: gasModel schedule ${name} names no hardforks`);
    schedules[name] = {
      hardforks: sch.hardforks,
      constants: constants(`${name}.constants`, sch.constants),
      ...(sch.executionGas
        ? { executionGas: constants(`${name}.executionGas`, sch.executionGas) }
        : {}),
      floor: floorOf(`${name}.floor`, sch.floor),
      // The all-gas error; where the cap counts execution gas only (amsterdam), the execution error the cap
      // condition is tested against (gas/model.json planning.headroomCovers).
      maxAbsErrorPercent: sch.maxAbsErrorPercent,
      ...(sch.maxAbsExecutionErrorPercent !== undefined
        ? { maxAbsExecutionErrorPercent: sch.maxAbsExecutionErrorPercent }
        : {}),
    };
  }
  if (!schedules.prague) throw new Error("codegen: gasModel has no prague schedule");
  const env = g.envelope ?? {};
  if (typeof env.txGasCap !== "number" || typeof env.headroomPercent !== "number")
    throw new Error("codegen: gasModel.envelope needs txGasCap and headroomPercent");
  let src = header(["release/release.json"]);
  src +=
    "/**\n * The contracts' fitted gas model, by fee schedule (release.json gasModel). Planning only; eth_estimateGas on\n * the exact call decides before sending. `executionGas` is set where the per-transaction cap counts execution gas\n * only (then `constants`, all gas, must also fit the block). Never apply one schedule's constants to another.\n */\n";
  src += `export const GAS_SCHEDULES = ${literal(schedules)} as const;\n\n`;
  src +=
    "/** The per-transaction gas cap (EIP-7825) and the planning headroom the contracts use. */\n";
  src += `export const GAS_ENVELOPE = ${literal({ txGasCap: env.txGasCap, headroomPercent: env.headroomPercent })} as const;\n\n`;
  const pl = g.planning;
  if (
    typeof pl?.txGasCap !== "number" ||
    typeof pl?.headroomPercent !== "number" ||
    typeof pl?.limits?.maxActions !== "number" ||
    typeof pl?.limits?.maxBindsPerPublication !== "number" ||
    typeof pl?.limits?.maxBodyBytesPerPublication !== "number"
  )
    throw new Error("codegen: gasModel.planning needs txGasCap, headroomPercent and limits");
  src +=
    "/** The planning rule (gas/model.json planning): inside `limits`, and max(E, V) ≤ ⌊txGasCap × (100 − headroomPercent) / 100⌋. */\n";
  src += `export const GAS_PLANNING = ${literal({ txGasCap: pl.txGasCap, headroomPercent: pl.headroomPercent, limits: pl.limits })} as const;\n\n`;
  const pan = g.tagLists?.priceAsNew;
  if (!Array.isArray(pan?.entries) || typeof pan?.entriesMultipleOf !== "number")
    throw new Error("codegen: gasModel.tagLists.priceAsNew needs entries and entriesMultipleOf");
  src +=
    "/** A roll-up list holding one of `entries`, or a multiple of `entriesMultipleOf` (zero included), takes a fresh word on its next append: price that append as new. */\n";
  src += `export const GAS_TAG_LISTS = ${literal({ priceAsNew: { entries: pan.entries, entriesMultipleOf: pan.entriesMultipleOf } })} as const;\n\n`;
  const rd = g.reads;
  if (typeof rd?.callGasCap !== "number" || !rd?.recommended?.prague)
    throw new Error("codegen: gasModel.reads needs callGasCap and recommended bounds");
  src +=
    "/** The topic readers' bounds (gas/model.json reads): page × Lens per view, rows per call and entries read per call, keeping one call under callGasCap. */\n";
  src += `export const GAS_READS = ${literal({ callGasCap: rd.callGasCap, marginPercent: rd.marginPercent, recommended: rd.recommended })} as const;\n`;
  files["gas.ts"] = src;
}

// ---- Protocol inputs provenance (what this SDK build was generated from)
{
  let src = header([]);
  src +=
    "/** The contracts commit (and, once release pinning starts, the release digest) this SDK build was generated from. */\n";
  src += `export const PROTOCOL_INPUTS = ${literal({ contractsCommit: lock.contracts.commit, releaseDigest: lock.contracts.releaseDigest })} as const;\n`;
  files["inputs.ts"] = src;
}

mkdirSync(OUT, { recursive: true });
let drift = 0;
for (const [name, content] of Object.entries(files)) {
  const path = join(OUT, name);
  if (check) {
    const have = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (have !== content) {
      fail(`generated/${name} is stale (run pnpm generate)`);
      drift++;
    }
  } else {
    writeFileSync(path, content);
  }
}
if (!drift)
  ok(
    `${check ? "checked" : "wrote"} ${Object.keys(files).length} generated files (${Object.entries(
      files,
    )
      .map(([n, c]) => `${n}:${sha(c)}`)
      .join(" ")})`,
  );
